const fs = require('fs');
const path = require('path');

// Create routes-manifest.json for Vercel compatibility
// This file is required by Vercel but not generated by Next.js static export
const routesManifest = {
  version: 3,
  pages404: true,
  basePath: process.env.NEXT_PUBLIC_BASE_PATH || '',
  redirects: [],
  rewrites: [],
  headers: [],
  dynamicRoutes: [],
  staticRoutes: [],
  dataRoutes: [],
  rsc: {
    header: 'RSC',
    varyHeader: 'RSC, Next-Router-State-Tree, Next-Router-Prefetch',
    prefetchHeader: 'Next-Router-Prefetch',
    contentTypeHeader: 'text/x-component'
  }
};

const outDir = path.join(process.cwd(), 'out');
const manifestPath = path.join(outDir, 'routes-manifest.json');

// Ensure out directory exists
if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

// Write routes-manifest.json
fs.writeFileSync(manifestPath, JSON.stringify(routesManifest, null, 2));
console.log('✅ Created routes-manifest.json for Vercel compatibility');

